7	import * as path from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	import { Storage } from '../config/storage.js';
10	import { type SkillDefinition, loadSkillsFromDir } from './skillLoader.js';
11	import type { GeminiCLIExtension } from '../config/config.js';
12	import { debugLogger } from '../utils/debugLogger.js';
13	import { coreEvents } from '../utils/events.js';
14	
15	export { type SkillDefinition };
16	
17	export class SkillManager {
18	  private skills: SkillDefinition[] = [];
19	  private activeSkillNames: Set<string> = new Set();
20	  private adminSkillsEnabled = true;
21	
22	  /**
23	   * Clears all discovered skills.
24	   */
25	  clearSkills(): void {
26	    this.skills = [];
27	  }
28	
29	  /**
30	   * Sets administrative settings for skills.
31	   */
32	  setAdminSettings(enabled: boolean): void {
33	    this.adminSkillsEnabled = enabled;
34	  }
35	
36	  /**
37	   * Returns true if skills are enabled by the admin.
38	   */
39	  isAdminEnabled(): boolean {
40	    return this.adminSkillsEnabled;
41	  }
42	
43	  /**
44	   * Discovers skills from standard user and workspace locations, as well as extensions.
45	   * Precedence: Extensions (lowest) -> User -> Workspace (highest).
46	   */
47	  async discoverSkills(
48	    storage: Storage,
49	    extensions: GeminiCLIExtension[] = [],
50	    isTrusted: boolean = false,
51	  ): Promise<void> {
52	    this.clearSkills();
53	
54	    // 1. Built-in skills (lowest precedence)
55	    await this.discoverBuiltinSkills();
56	
57	    // 2. Extension skills
58	    for (const extension of extensions) {
59	      if (extension.isActive && extension.skills) {
60	        this.addSkillsWithPrecedence(extension.skills);
61	      }
62	    }
63	
64	    // 3. User skills
65	    const userSkills = await loadSkillsFromDir(Storage.getUserSkillsDir());
66	    this.addSkillsWithPrecedence(userSkills);
67	
68	    // 3.1 User agent skills alias (.agents/skills)
69	    const userAgentSkills = await loadSkillsFromDir(
70	      Storage.getUserAgentSkillsDir(),
71	    );
72	    this.addSkillsWithPrecedence(userAgentSkills);
73	
74	    // 4. Workspace skills (highest precedence)
75	    if (!isTrusted) {
76	      debugLogger.debug(
77	        'Workspace skills disabled because folder is not trusted.',
78	      );
79	      return;
80	    }
81	
82	    const projectSkills = await loadSkillsFromDir(
83	      storage.getProjectSkillsDir(),
84	    );
85	    this.addSkillsWithPrecedence(projectSkills);
86	
87	    // 4.1 Workspace agent skills alias (.agents/skills)
88	    const projectAgentSkills = await loadSkillsFromDir(
89	      storage.getProjectAgentSkillsDir(),
90	    );
91	    this.addSkillsWithPrecedence(projectAgentSkills);
92	  }
93	
94	  /**
95	   * Discovers built-in skills.
96	   */
97	  private async discoverBuiltinSkills(): Promise<void> {
98	    const __dirname = path.dirname(fileURLToPath(import.meta.url));
99	    const builtinDir = path.join(__dirname, 'builtin');
100	
101	    const builtinSkills = await loadSkillsFromDir(builtinDir);
102	
103	    for (const skill of builtinSkills) {
104	      skill.isBuiltin = true;
105	    }
106	
107	    this.addSkillsWithPrecedence(builtinSkills);
108	  }
109	
110	  /**
111	   * Adds skills to the manager programmatically.
112	   */
113	  addSkills(skills: SkillDefinition[]): void {
114	    this.addSkillsWithPrecedence(skills);
115	  }
116	
117	  private addSkillsWithPrecedence(newSkills: SkillDefinition[]): void {
118	    const skillMap = new Map<string, SkillDefinition>(
119	      this.skills.map((s) => [s.name, s]),
120	    );
121	
122	    for (const newSkill of newSkills) {
123	      const existingSkill = skillMap.get(newSkill.name);
124	      if (existingSkill && existingSkill.location !== newSkill.location) {
125	        if (existingSkill.isBuiltin) {
126	          debugLogger.warn(
127	            `Skill "${newSkill.name}" from "${newSkill.location}" is overriding the built-in skill.`,
128	          );
129	        } else {
130	          coreEvents.emitFeedback(
131	            'warning',
132	            `Skill conflict detected: "${newSkill.name}" from "${newSkill.location}" is overriding the same skill from "${existingSkill.location}".`,
133	          );
134	        }
135	      }
136	      skillMap.set(newSkill.name, newSkill);
137	    }
138	
139	    this.skills = Array.from(skillMap.values());
140	  }
141	
142	  /**
143	   * Returns the list of enabled discovered skills.
144	   */
145	  getSkills(): SkillDefinition[] {
146	    return this.skills.filter((s) => !s.disabled);
147	  }
148	
149	  /**
150	   * Returns the list of enabled discovered skills that should be displayed in the UI.
151	   * This excludes built-in skills.
152	   */
153	  getDisplayableSkills(): SkillDefinition[] {
154	    return this.skills.filter((s) => !s.disabled && !s.isBuiltin);
155	  }
156	
157	  /**
158	   * Returns all discovered skills, including disabled ones.
159	   */
160	  getAllSkills(): SkillDefinition[] {
161	    return this.skills;
162	  }
163	
164	  /**
165	   * Filters discovered skills by name.
166	   */
167	  filterSkills(predicate: (skill: SkillDefinition) => boolean): void {
168	    this.skills = this.skills.filter(predicate);
169	  }
170	
171	  /**
172	   * Sets the list of disabled skill names.
173	   */
174	  setDisabledSkills(disabledNames: string[]): void {
175	    const lowercaseDisabledNames = disabledNames.map((n) => n.toLowerCase());
176	    for (const skill of this.skills) {
177	      skill.disabled = lowercaseDisabledNames.includes(
178	        skill.name.toLowerCase(),
179	      );
180	    }
181	  }
182	
183	  /**
184	   * Reads the full content (metadata + body) of a skill by name.
185	   */
186	  getSkill(name: string): SkillDefinition | null {
187	    const lowercaseName = name.toLowerCase();
188	    return (
189	      this.skills.find((s) => s.name.toLowerCase() === lowercaseName) ?? null
190	    );
191	  }
192	
193	  /**
194	   * Activates a skill by name.
195	   */
196	  activateSkill(name: string): void {
197	    this.activeSkillNames.add(name);
198	  }
199	
200	  /**
201	   * Checks if a skill is active.
202	   */
203	  isSkillActive(name: string): boolean {
204	    return this.activeSkillNames.has(name);
205	  }
206	}
