46	/**
47	 * Metadata for a single extraction run.
48	 */
49	export interface ExtractionRun {
50	  runAt: string;
51	  sessionIds: string[];
52	  skillsCreated: string[];
53	}
54	
55	/**
56	 * Tracks extraction history with per-run metadata.
57	 */
58	export interface ExtractionState {
59	  runs: ExtractionRun[];
60	}
61	
62	/**
63	 * Returns all session IDs that have been processed across all runs.
64	 */
65	export function getProcessedSessionIds(state: ExtractionState): Set<string> {
66	  const ids = new Set<string>();
67	  for (const run of state.runs) {
68	    for (const id of run.sessionIds) {
69	      ids.add(id);
70	    }
71	  }
72	  return ids;
