75	function isLockInfo(value: unknown): value is LockInfo {
76	  return (
77	    typeof value === 'object' &&
78	    value !== null &&
79	    'pid' in value &&
80	    typeof value.pid === 'number' &&
81	    'startedAt' in value &&
82	    typeof value.startedAt === 'string'
83	  );
84	}
