86	function isConversationRecord(value: unknown): value is ConversationRecord {
87	  return (
88	    typeof value === 'object' &&
89	    value !== null &&
90	    'sessionId' in value &&
91	    typeof value.sessionId === 'string' &&
92	    'messages' in value &&
93	    Array.isArray(value.messages) &&
94	    'projectHash' in value &&
