122	/**
123	 * Attempts to acquire an exclusive lock file using O_CREAT | O_EXCL.
124	 * Returns true if the lock was acquired, false if another instance owns it.
125	 */
126	export async function tryAcquireLock(
127	  lockPath: string,
128	  retries = 1,
129	): Promise<boolean> {
130	  const lockInfo: LockInfo = {
131	    pid: process.pid,
132	    startedAt: new Date().toISOString(),
133	  };
134	
135	  try {
136	    // Atomic create-if-not-exists
137	    const fd = await fs.open(
138	      lockPath,
139	      fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_WRONLY,
140	    );
141	    try {
142	      await fd.writeFile(JSON.stringify(lockInfo));
143	    } finally {
144	      await fd.close();
145	    }
146	    return true;
147	  } catch (error: unknown) {
148	    if (isNodeError(error) && error.code === 'EEXIST') {
149	      // Lock exists — check if it's stale
150	      if (retries > 0 && (await isLockStale(lockPath))) {
151	        debugLogger.debug('[MemoryService] Cleaning up stale lock file');
152	        await releaseLock(lockPath);
153	        return tryAcquireLock(lockPath, retries - 1);
154	      }
155	      debugLogger.debug(
156	        '[MemoryService] Lock held by another instance, skipping',
157	      );
158	      return false;
159	    }
160	    throw error;
161	  }
162	}
163	
164	/**
165	 * Checks if a lock file is stale (owner PID is dead or lock is too old).
166	 */
167	export async function isLockStale(lockPath: string): Promise<boolean> {
168	  try {
169	    const content = await fs.readFile(lockPath, 'utf-8');
170	    const parsed: unknown = JSON.parse(content);
171	    if (!isLockInfo(parsed)) {
172	      return true; // Invalid lock data — treat as stale
173	    }
174	    const lockInfo = parsed;
175	
176	    // Check if PID is still alive
177	    try {
178	      process.kill(lockInfo.pid, 0);
179	    } catch {
180	      // PID is dead — lock is stale
181	      return true;
182	    }
183	
184	    // Check if lock is too old
185	    const lockAge = Date.now() - new Date(lockInfo.startedAt).getTime();
186	    if (lockAge > LOCK_STALE_MS) {
187	      return true;
188	    }
189	
190	    return false;
191	  } catch {
192	    // Can't read lock — treat as stale
193	    return true;
194	  }
195	}
196	
197	/**
198	 * Releases the lock file.
199	 */
200	export async function releaseLock(lockPath: string): Promise<void> {
201	  try {
202	    await fs.unlink(lockPath);
203	  } catch (error: unknown) {
204	    if (isNodeError(error) && error.code === 'ENOENT') {
205	      return; // Already removed
206	    }
207	    debugLogger.warn(
208	      `[MemoryService] Failed to release lock: ${error instanceof Error ? error.message : String(error)}`,
209	    );
210	  }
211	}
