31	async function listAction(
32	  context: CommandContext,
33	  args: string,
34	): Promise<void | SlashCommandActionReturn> {
35	  const subArgs = args.trim().split(/\s+/);
36	
37	  // Default to SHOWING descriptions. The user can hide them with 'nodesc'.
38	  let useShowDescriptions = true;
39	  let showAll = false;
40	
41	  for (const arg of subArgs) {
42	    if (arg === 'nodesc' || arg === '--nodesc') {
43	      useShowDescriptions = false;
44	    } else if (arg === 'all' || arg === '--all') {
45	      showAll = true;
46	    }
47	  }
48	
49	  const skillManager = context.services.agentContext?.config.getSkillManager();
50	  if (!skillManager) {
51	    context.ui.addItem({
52	      type: MessageType.ERROR,
53	      text: 'Could not retrieve skill manager.',
54	    });
55	    return;
56	  }
57	
58	  const skills = showAll
59	    ? skillManager.getAllSkills()
60	    : skillManager.getAllSkills().filter((s) => !s.isBuiltin);
61	
62	  const skillsListItem: HistoryItemSkillsList = {
63	    type: MessageType.SKILLS_LIST,
64	    skills: skills.map((skill) => ({
65	      name: skill.name,
66	      description: skill.description,
67	      disabled: skill.disabled,
68	      location: skill.location,
69	      body: skill.body,
70	      isBuiltin: skill.isBuiltin,
71	    })),
72	    showDescriptions: useShowDescriptions,
73	  };
74	
75	  context.ui.addItem(skillsListItem);
76	}
