78	async function linkAction(
79	  context: CommandContext,
80	  args: string,
81	): Promise<void | SlashCommandActionReturn> {
82	  const parts = args.trim().split(/\s+/);
83	  const sourcePath = parts[0];
84	
85	  if (!sourcePath) {
86	    context.ui.addItem({
87	      type: MessageType.ERROR,
88	      text: 'Usage: /skills link <path> [--scope user|workspace]',
89	    });
90	    return;
91	  }
92	
93	  let scopeArg = 'user';
94	  if (parts.length >= 3 && parts[1] === '--scope') {
95	    scopeArg = parts[2];
96	  } else if (parts.length >= 2 && parts[1].startsWith('--scope=')) {
97	    scopeArg = parts[1].split('=')[1];
98	  }
99	
100	  const scope = scopeArg === 'workspace' ? 'workspace' : 'user';
101	
102	  try {
103	    await linkSkill(
104	      sourcePath,
105	      scope,
106	      (msg) =>
107	        context.ui.addItem({
108	          type: MessageType.INFO,
109	          text: msg,
110	        }),
111	      async (skills, targetDir) => {
112	        const consentString = await skillsConsentString(
113	          skills,
114	          sourcePath,
115	          targetDir,
116	          true,
117	        );
118	        return requestConsentInteractive(
119	          consentString,
120	          context.ui.setConfirmationRequest.bind(context.ui),
121	        );
122	      },
123	    );
124	
125	    context.ui.addItem({
126	      type: MessageType.INFO,
127	      text: `Successfully linked skills from "${sourcePath}" (${scope}).`,
128	    });
129	
130	    if (context.services.agentContext?.config) {
131	      await context.services.agentContext.config.reloadSkills();
132	    }
133	  } catch (error) {
134	    context.ui.addItem({
135	      type: MessageType.ERROR,
136	      text: `Failed to link skills: ${getErrorMessage(error)}`,
137	    });
138	  }
139	}
