156	      {
157	        type: MessageType.ERROR,
158	        text: getAdminErrorMessage(
159	          'Agent skills',
160	          context.services.agentContext?.config ?? undefined,
161	        ),
162	      },
163	      Date.now(),
164	    );
165	    return;
166	  }
167	
168	  const skill = skillManager?.getSkill(skillName);
169	  if (!skill) {
170	    context.ui.addItem(
171	      {
172	        type: MessageType.ERROR,
173	        text: `Skill "${skillName}" not found.`,
174	      },
175	      Date.now(),
176	    );
177	    return;
178	  }
179	
180	  const scope = context.services.settings.workspace.path
