import type React from 'react';
import { useCallback, useEffect, useState } from 'react';
import { Box, Text } from 'ink';
import {
  listInboxSkills,
  moveInboxSkill,
  dismissInboxSkill,
  type Config,
  type InboxSkill,
} from '@google/gemini-cli-core';
import { theme } from '../semantic-colors.js';
import { useKeypress, type Key } from '../hooks/useKeypress.js';
import { Command } from '../key/keyMatchers.js';
import { useKeyMatchers } from '../hooks/useKeyMatchers.js';
import {
  RadioButtonSelect,
  type RadioSelectItem,
} from './shared/RadioButtonSelect.js';
import { DialogFooter } from './shared/DialogFooter.js';

export interface SkillInboxDialogProps {
  config: Config;
  onClose: () => void;
  onReloadSkills?: () => void | Promise<void>;
}

type InboxAction = 'global' | 'project' | 'dismiss' | 'back';

export const SkillInboxDialog: React.FC<SkillInboxDialogProps> = ({
  config,
  onClose,
  onReloadSkills,
}) => {
  const keyMatchers = useKeyMatchers();
  const [skills, setSkills] = useState<InboxSkill[] | null>(null);
  const [selected, setSelected] = useState<InboxSkill | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const isTrusted = config.isTrustedFolder();

  const refresh = useCallback(async () => {
    try {
      const inbox = await listInboxSkills(config);
      setSkills(inbox);
    } catch (e) {
      setSkills([]);
      setError(
        `Failed to load skill inbox: ${
          e instanceof Error ? e.message : String(e)
        }`,
      );
    }
  }, [config]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const handleSkillSelect = useCallback((skill: InboxSkill) => {
    setError(null);
    setSelected(skill);
  }, []);

  const handleActionSelect = useCallback(
    async (action: InboxAction) => {
      if (!selected || busy) {
        if (action === 'back') {
          setSelected(null);
          setError(null);
        }
        return;
      }

      if (action === 'back') {
        setSelected(null);
        setError(null);
        return;
      }

      setBusy(true);
      try {
        const result =
          action === 'dismiss'
            ? await dismissInboxSkill(config, selected.dirName)
            : await moveInboxSkill(config, selected.dirName, action);

        if (!result.success) {
          setError(result.message);
          return;
        }

        setError(null);
        setSelected(null);
        await refresh();
        if (action !== 'dismiss') {
          await onReloadSkills?.();
        }
      } finally {
        setBusy(false);
      }
    },
    [selected, busy, config, refresh, onReloadSkills],
  );

  useKeypress(
    (key: Key) => {
      if (keyMatchers[Command.ESCAPE](key)) {
        if (selected) {
          setSelected(null);
          setError(null);
        } else {
          onClose();
        }
        return true;
      }
      return false;
    },
    { isActive: true, priority: true },
  );

  const renderBody = () => {
    if (skills === null) {
      return <Text color={theme.text.secondary}>Loading skill inbox…</Text>;
    }

    if (selected) {
      const items: Array<RadioSelectItem<InboxAction>> = [
        {
          key: 'global',
          label: 'Install globally (~/.gemini/skills)',
          value: 'global',
        },
        {
          key: 'project',
          label: isTrusted
            ? 'Install for this project (.gemini/skills)'
            : 'Install for this project (unavailable — workspace not trusted)',
          value: 'project',
          disabled: !isTrusted,
        },
        {
          key: 'dismiss',
          label: 'Dismiss (delete from inbox)',
          value: 'dismiss',
        },
        {
          key: 'back',
          label: 'Back',
          value: 'back',
        },
      ];

      return (
        <Box flexDirection="column">
          <Text>
            <Text bold>{selected.name}</Text>
          </Text>
          {selected.description ? (
            <Text color={theme.text.secondary} wrap="wrap">
              {selected.description}
            </Text>
          ) : null}
          <Box marginTop={1}>
            <RadioButtonSelect<InboxAction>
              items={items}
              onSelect={(value) => {
                void handleActionSelect(value);
              }}
              isFocused={!busy}
            />
          </Box>
        </Box>
      );
    }

    if (skills.length === 0) {
      return (
        <Text color={theme.text.secondary}>
          Your skill inbox is empty. New skills are extracted automatically from
          your past sessions.
        </Text>
      );
    }

    const items: Array<RadioSelectItem<InboxSkill>> = skills.map((skill) => ({
      key: skill.dirName,
      label: skill.name,
      sublabel: skill.description,
      value: skill,
    }));

    return (
      <RadioButtonSelect<InboxSkill>
        items={items}
        onSelect={handleSkillSelect}
        isFocused={!busy}
      />
    );
  };

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor={theme.border.default}
      paddingX={2}
      paddingY={1}
      width="100%"
    >
      <Text bold>Skill Inbox</Text>
      <Text color={theme.text.secondary}>
        Review skills auto-extracted from your past sessions.
      </Text>

      {error ? (
        <Box marginTop={1}>
          <Text color={theme.status.error}>{error}</Text>
        </Box>
      ) : null}

      <Box marginTop={1} flexDirection="column">
        {renderBody()}
      </Box>

      <DialogFooter
        primaryAction="Enter to select"
        navigationActions="↑/↓ to navigate"
        cancelAction={selected ? 'Esc to go back' : 'Esc to close'}
      />
    </Box>
  );
};
