import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import type { Config } from '../config/config.js';
import { Storage } from '../config/storage.js';
import { debugLogger } from '../utils/debugLogger.js';
import { isNodeError } from '../utils/errors.js';
import { FRONTMATTER_REGEX, parseFrontmatter } from './skillLoader.js';

const STATE_FILENAME = '.extraction-state.json';

/**
 * The destination a skill can be moved to from the inbox.
 * - 'global' installs the skill for the current user (~/.gemini/skills).
 * - 'project' installs the skill for the current workspace (.gemini/skills).
 */
export type InboxDestination = 'global' | 'project';

/**
 * A skill that has been auto-extracted from past sessions and is waiting in the
 * inbox for the user to review, install, or dismiss.
 */
export interface InboxSkill {
  /** The name of the skill's directory inside the inbox. */
  dirName: string;
  /** The skill's display name (from SKILL.md frontmatter). */
  name: string;
  /** A concise description of what the skill does. */
  description: string;
  /** ISO timestamp of when the skill was extracted. */
  extractedAt: string;
}

/**
 * The result of an inbox action (move or dismiss).
 */
export interface InboxActionResult {
  /** Whether the action succeeded. */
  success: boolean;
  /** A user-facing message describing the outcome. */
  message: string;
}

/**
 * Validates that a skill directory name is a plain path segment and cannot be
 * used to escape the inbox directory (path traversal / absolute paths).
 */
export function isValidSkillDirName(dirName: string): boolean {
  if (typeof dirName !== 'string') {
    return false;
  }
  const trimmed = dirName.trim();
  if (trimmed === '' || trimmed === '.' || trimmed === '..') {
    return false;
  }
  // Reject any path separators, null bytes, or drive-relative segments.
  if (/[/\\]/.test(dirName) || dirName.includes('\0')) {
    return false;
  }
  // The name must be a single, self-referential path segment.
  if (path.basename(dirName) !== dirName || path.isAbsolute(dirName)) {
    return false;
  }
  return true;
}

/**
 * Reads the extraction state file and builds a map of skill directory name ->
 * the ISO timestamp of the (most recent) run that created it.
 */
async function buildExtractedAtMap(
  memoryDir: string,
): Promise<Map<string, string>> {
  const map = new Map<string, string>();
  const statePath = path.join(memoryDir, STATE_FILENAME);
  try {
    const content = await fs.readFile(statePath, 'utf-8');
    const parsed: unknown = JSON.parse(content);
    if (
      parsed &&
      typeof parsed === 'object' &&
      'runs' in parsed &&
      Array.isArray((parsed as { runs: unknown[] }).runs)
    ) {
      for (const run of (parsed as { runs: unknown[] }).runs) {
        if (
          run &&
          typeof run === 'object' &&
          'runAt' in run &&
          typeof (run as { runAt: unknown }).runAt === 'string' &&
          'skillsCreated' in run &&
          Array.isArray((run as { skillsCreated: unknown[] }).skillsCreated)
        ) {
          const runAt = (run as { runAt: string }).runAt;
          for (const created of (run as { skillsCreated: unknown[] })
            .skillsCreated) {
            if (typeof created === 'string') {
              map.set(created, runAt);
            }
          }
        }
      }
    }
  } catch (error) {
    debugLogger.debug('[SkillInbox] Failed to read extraction state:', error);
  }
  return map;
}

/**
 * Reads the name/description from a skill's SKILL.md file, falling back to the
 * directory name when the frontmatter is missing or unparseable.
 */
async function readInboxSkillMetadata(
  skillDir: string,
  dirName: string,
): Promise<{ name: string; description: string }> {
  try {
    const content = await fs.readFile(
      path.join(skillDir, 'SKILL.md'),
      'utf-8',
    );
    const match = content.match(FRONTMATTER_REGEX);
    if (match) {
      const parsed = parseFrontmatter(match[1]);
      if (parsed) {
        return { name: parsed.name, description: parsed.description };
      }
    }
  } catch (error) {
    debugLogger.debug(
      `[SkillInbox] Failed to read metadata for "${dirName}":`,
      error,
    );
  }
  return { name: dirName, description: '' };
}

/**
 * Lists the skills currently waiting in the inbox (the memory-extracted skills
 * directory). Returns an empty array when the inbox directory is missing or
 * contains no skills.
 */
export async function listInboxSkills(config: Config): Promise<InboxSkill[]> {
  const inboxDir = config.storage.getProjectSkillsMemoryDir();

  let entries: Array<import('node:fs').Dirent>;
  try {
    entries = await fs.readdir(inboxDir, { withFileTypes: true });
  } catch {
    // Inbox directory doesn't exist yet.
    return [];
  }

  const extractedAtMap = await buildExtractedAtMap(
    config.storage.getProjectMemoryTempDir(),
  );

  const skills: InboxSkill[] = [];
  for (const entry of entries) {
    if (!entry.isDirectory()) {
      continue;
    }

    const dirName = entry.name;
    const skillDir = path.join(inboxDir, dirName);

    // Only surface directories that actually contain a SKILL.md file.
    try {
      await fs.access(path.join(skillDir, 'SKILL.md'));
    } catch {
      continue;
    }

    const { name, description } = await readInboxSkillMetadata(
      skillDir,
      dirName,
    );

    let extractedAt = extractedAtMap.get(dirName);
    if (!extractedAt) {
      try {
        const stats = await fs.stat(skillDir);
        const created =
          stats.birthtimeMs > 0 ? stats.birthtime : stats.mtime;
        extractedAt = created.toISOString();
      } catch {
        extractedAt = '';
      }
    }

    skills.push({ dirName, name, description, extractedAt });
  }

  // Most-recently-extracted first.
  skills.sort((a, b) => b.extractedAt.localeCompare(a.extractedAt));

  return skills;
}

/**
 * Moves a skill out of the inbox and into the user's global or the project's
 * workspace skills directory. Validates the directory name, detects name
 * conflicts in the destination, and returns a descriptive result.
 */
export async function moveInboxSkill(
  config: Config,
  dirName: string,
  destination: InboxDestination,
): Promise<InboxActionResult> {
  if (!isValidSkillDirName(dirName)) {
    return {
      success: false,
      message: `Invalid skill name: "${dirName}".`,
    };
  }

  const inboxDir = config.storage.getProjectSkillsMemoryDir();
  const source = path.join(inboxDir, dirName);

  try {
    const stats = await fs.stat(source);
    if (!stats.isDirectory()) {
      return {
